<div class="card mb-4"><div class="card-header"><h2 class="card-title">Monthly search credits</h2></div><div class="card-body"><div class="row g-3">@foreach(['allowance'=>'Monthly allowance','used'=>'Used credits','reserved'=>'Reserved credits','remaining'=>'Remaining credits'] as $key=>$label)<div class="col-6 col-lg-3"><div class="subheader">{{ $label }}</div><div class="h2 mt-2 mb-0" data-credit-{{ $key }}>{{ number_format($credits[$key]) }}</div></div>@endforeach</div><div class="progress mt-3" role="progressbar" aria-label="Used and reserved monthly credits" aria-valuenow="{{ $credits['used']+$credits['reserved'] }}" aria-valuemin="0" aria-valuemax="{{ max(1,$credits['allowance']) }}"><div class="progress-bar bg-primary" style="width:{{ min(100,($credits['used']+$credits['reserved'])/max(1,$credits['allowance'])*100) }}%"></div></div><p class="text-secondary small mt-3 mb-0">Next reset: {{ $credits['reset']->format('d M Y, H:i') }} UTC. No rollover. Completed responses use credits; confirmed failures release them. Uncertain requests retain a reservation. Monitoring remains subject to service availability.</p></div></div>
